package com.badspell.server;

import com.badspell.content.*;
import com.badspell.conduction.*;
import com.badspell.formula.*;
import com.badspell.production.*;
import java.util.*;
import java.util.function.Consumer;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.Registries;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.event.RegisterGameTestsEvent;
import net.neoforged.neoforge.registries.DeferredRegister;

/** M1 acceptance boundaries: generic devices, offline fields, conductor conservation and real persistence. */
public final class M1CompletionTests {
    private static final DeferredRegister<Consumer<GameTestHelper>> FUNCTIONS=DeferredRegister.create(Registries.TEST_FUNCTION,"badspell");
    private static final List<String> NAMES=new ArrayList<>();
    private static void test(String name,Consumer<GameTestHelper> body){NAMES.add(name);FUNCTIONS.register(name,()->body);}
    private static ServerPlayer owner(GameTestHelper h){var p=new net.neoforged.neoforge.common.util.FakePlayer(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"M1Owner"));var at=h.absolutePos(new BlockPos(2,1,2));p.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);for(String id:com.badspell.research.ResearchRules.ids())com.badspell.progression.ResearchProgress.learn(p,id);return p;}
    private static StationBlockEntity station(GameTestHelper h,String kind,BlockPos at,ServerPlayer owner,int charge){h.getLevel().setBlockAndUpdate(at,ModContent.STATIONS.get(kind).get().defaultBlockState());var station=(StationBlockEntity)h.getLevel().getBlockEntity(at);station.claim(owner);var cell=new ItemStack(ModItems.FIELD_CELL_Q3.get());CustomData.update(DataComponents.CUSTOM_DATA,cell,t->t.putInt("badspell_fl",charge));station.setItem(6,cell);station.setItem(11,new ItemStack(ModContent.item("cell_adapter")));return station;}
    private static void plate(StationBlockEntity station,Formula formula){try{var item=new ItemStack(ModContent.item("inscribed_rune_plate"));byte[] bytes=FormulaCodec.encode(formula);CustomData.update(DataComponents.CUSTOM_DATA,item,t->{t.putByteArray("badspell_formula",bytes);t.putString("badspell_checksum",new FormulaSnapshot(formula).checksum());});station.setItem(0,item);}catch(java.io.IOException e){throw new IllegalStateException(e);}}
    private static Direction direction(BlockPos from,BlockPos to){for(var direction:Direction.values())if(from.relative(direction).equals(to))return direction;throw new IllegalArgumentException();}
    private static Formula fixed(Formula formula,Value.Position at){var nodes=new ArrayList<Formula.Node>();for(var n:formula.nodes())nodes.add(n.id().equals("target")?new Formula.Node(n.id(),"badspell:position",n.x(),n.y(),Map.of("value",at)):n);return new Formula(formula.id(),formula.owner(),1,formula.title(),nodes,formula.edges().stream().filter(e->!e.to().equals("target")).toList(),formula.output(),1000);}
    static {
        test("m1_air_cast_target_range",h->{var p=owner(h);p.setXRot(-90);for(int y=1;y<=20;y++)h.getLevel().setBlockAndUpdate(p.blockPosition().above(y),Blocks.AIR.defaultBlockState());var target=com.badspell.magic.SpellTargets.position(p);h.assertTrue(target.distSqr(p.blockPosition())<=144,"A miss is clamped within the advertised cast range");var glove=new ItemStack(ModItems.RUNE_GLOVE.get());try{com.badspell.item.GloveFormulas.importSnapshot(glove,ExampleFormulas.light(p.getUUID()),p.getUUID());}catch(java.io.IOException e){throw new IllegalStateException(e);}p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,glove);p.getInventory().setItem(1,new ItemStack(ModItems.FIELD_CELL.get()));MagicActions.cast(p,net.minecraft.world.InteractionHand.MAIN_HAND);h.assertTrue(p.getInventory().getItem(1).getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getIntOr("badspell_fl",100)==70,"A real empty-air glove cast succeeds and pays exactly 30 FL");h.assertTrue(com.badspell.lighting.FieldLightSources.emission(h.getLevel(),target)==3,"The empty-air target actually emits light");h.succeed();});
        test("m1_device_shield_owner_identity",h->{var p=owner(h);var pos=h.absolutePos(new BlockPos(2,1,2));station(h,"rune_holder",pos,p,100);var actor=DeviceCasters.at(h.getLevel(),p.getUUID(),pos);var pig=h.spawn(net.minecraft.world.entity.EntityTypes.PIG,new BlockPos(3,1,3));pig.setUUID(p.getUUID());pig.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);var effect=new Value.Effect("badspell:shield",new Value.Region(SpellEffects.position(h.getLevel(),pig.blockPosition()),0),1,100,5,5);var field=SpellFields.get(h.getLevel()).add(actor,effect,h.getLevel().getGameTime());SpellFields.advance(h.getLevel(),actor,field,h.getLevel().getGameTime());h.assertTrue(pig.getDeltaMovement().lengthSqr()==0,"Device shields recognize owner UUID rather than fake-player object identity");h.succeed();});
        test("m1_fork_repair_without_plate",h->{var p=owner(h);var at=h.absolutePos(new BlockPos(2,1,2));var bench=station(h,"arcane_workbench",at,p,100);var fork=new ItemStack(ModItems.RESONANCE_FORK.get());fork.setDamageValue(100);bench.setItem(0,fork);bench.setItem(1,new ItemStack(ModContent.item("rune_resin")));bench.setItem(2,new ItemStack(ModContent.item("field_crystal_shard")));h.runAfterDelay(85,()->{h.assertTrue(bench.getItem(7).is(ModItems.RESONANCE_FORK.get())&&bench.getItem(7).getDamageValue()==0,"Repair yields an undamaged fork without requiring another formula plate");h.assertTrue(bench.getItem(0).isEmpty()&&bench.getItem(1).isEmpty()&&bench.getItem(2).isEmpty(),"Repair consumes exactly the damaged fork and repair materials");h.assertTrue(bench.energyStored()==100,"Zero-FL repair does not spend stored charge");h.succeed();});});
        test("m1_conductor_conserves_and_limits",h->{var p=owner(h);var recv=h.absolutePos(new BlockPos(2,1,1));var send=h.absolutePos(new BlockPos(2,1,4));var a=station(h,"arcane_workbench",recv,p,0);var b=station(h,"arcane_workbench",send,p,200);var near=h.absolutePos(new BlockPos(2,1,2));var far=h.absolutePos(new BlockPos(2,1,3));h.getLevel().setBlockAndUpdate(near,ModContent.FIELD_CRYSTAL.get().defaultBlockState().setValue(FieldCrystalBlock.FACING,direction(near,recv)));h.getLevel().setBlockAndUpdate(far,ModContent.FIELD_CRYSTAL.get().defaultBlockState().setValue(FieldCrystalBlock.FACING,direction(far,near)));
            h.assertTrue(h.getLevel().getBlockEntity(near)==null,"Conductor has no buffer or block entity");h.assertTrue(CrystalConduction.pull(a,150)==80,"Q1 path carries at most 80 FL in a second");h.assertTrue(a.energyStored()==80&&b.energyStored()==120,"Exactly conserved across endpoints");h.assertTrue(CrystalConduction.pull(a,150)==0,"Repeated calls cannot bypass path rate");h.getLevel().setBlockAndUpdate(far,Blocks.AIR.defaultBlockState());h.assertTrue(CrystalConduction.pull(a,150)==0&&a.energyStored()+b.energyStored()==200,"Broken wire neither moves nor creates FL");h.succeed();});
        test("m1_conductor_direction_and_ownership",h->{var p=owner(h);var q=owner(h);var recv=h.absolutePos(new BlockPos(2,1,1));var wire=h.absolutePos(new BlockPos(2,1,2));var send=h.absolutePos(new BlockPos(2,1,3));var a=station(h,"arcane_workbench",recv,p,0);var b=station(h,"arcane_workbench",send,q,100);h.getLevel().setBlockAndUpdate(wire,ModContent.FIELD_CRYSTAL.get().defaultBlockState().setValue(FieldCrystalBlock.FACING,direction(wire,recv)));h.assertTrue(CrystalConduction.pull(a,50)==0,"Foreign station energy is not stolen");h.getLevel().setBlockAndUpdate(send,Blocks.AIR.defaultBlockState());var own=station(h,"arcane_workbench",send,p,100);h.getLevel().setBlockAndUpdate(wire,ModContent.FIELD_CRYSTAL.get().defaultBlockState().setValue(FieldCrystalBlock.FACING,direction(wire,send)));h.assertTrue(CrystalConduction.pull(a,50)==0,"Reverse tip blocks the route");h.getLevel().setBlockAndUpdate(wire,ModContent.FIELD_CRYSTAL.get().defaultBlockState().setValue(FieldCrystalBlock.FACING,direction(wire,recv)));h.assertTrue(CrystalConduction.pull(a,50)==50&&own.energyStored()==50,"Correct direction and ownership conduct");h.succeed();});
        test("m1_holder_area_effect",h->{var p=owner(h);var at=h.absolutePos(new BlockPos(2,1,2));var holder=station(h,"rune_holder",at,p,100);var center=at.above(2);var base=fixed(ExampleFormulas.light(p.getUUID()),SpellEffects.position(h.getLevel(),center));var nodes=new ArrayList<Formula.Node>();for(var n:base.nodes())nodes.add(n.id().equals("point")?new Formula.Node("point","badspell:sphere",0,0,Map.of("radius",new Value.Number(1))):n);var f=new Formula(base.id(),base.owner(),1,"area",nodes,base.edges(),base.output(),1000);plate(holder,f);for(var pos:SpellEffects.positions(new Value.Region(SpellEffects.position(h.getLevel(),center),1,Value.Shape.SPHERE,List.of(),new Value.Vector(0,0,1000),0)))h.getLevel().setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());h.assertTrue(holder.activatePlate(h.getLevel()),"Holder executes a sphere using the common adapter");h.assertTrue(holder.energyStored()==40,"Area cost is charged once");h.assertTrue(com.badspell.lighting.FieldLightSources.emission(h.getLevel(),center.above())==3,"Actual upper area cell emits light");h.succeed();});
        test("m1_holder_combined_offline",h->{var p=owner(h);var at=h.absolutePos(new BlockPos(2,1,2));var holder=station(h,"rune_holder",at,p,100);var pig=h.spawn(net.minecraft.world.entity.EntityTypes.PIG,new BlockPos(3,2,3));var base=ExampleFormulas.template("frost_push",p.getUUID(),SpellEffects.position(h.getLevel(),at.above()));var nodes=new ArrayList<Formula.Node>();for(var n:base.nodes())if(!Set.of("choose","none","available").contains(n.id()))nodes.add(n.id().equals("actor")?new Formula.Node(n.id(),"badspell:target_entity_id",0,0,Map.of("id",new Value.Text(pig.getUUID().toString()))):n);var edges=new ArrayList<>(base.edges().stream().filter(e->!Set.of("choose","none","available").contains(e.from())&&!Set.of("choose","none","available","actor").contains(e.to())).toList());edges.add(new Formula.Edge("combine","activate","effect"));var f=new Formula(UUID.randomUUID(),p.getUUID(),1,"device combo",nodes,edges,"activate",1000);plate(holder,f);h.assertTrue(h.getLevel().getServer().getPlayerList().getPlayer(p.getUUID())==null,"Owner is offline");h.assertTrue(holder.activatePlate(h.getLevel()),"Offline device activates a combined graph");h.assertTrue(pig.getDeltaMovement().lengthSqr()>.5&&pig.hasEffect(net.minecraft.world.effect.MobEffects.SLOWNESS),"Both world actions are real");h.assertTrue(holder.energyStored()==50,"Device pays 50 FL, no player FK");h.succeed();});
        test("m1_holder_offline_field_ticks",h->{var p=owner(h);var at=h.absolutePos(new BlockPos(2,1,2));var holder=station(h,"rune_holder",at,p,100);var pig=h.spawn(net.minecraft.world.entity.EntityTypes.PIG,new BlockPos(3,1,3));var f=fixed(ExampleFormulas.template("cold",p.getUUID(),SpellEffects.position(h.getLevel(),at)),SpellEffects.position(h.getLevel(),pig.blockPosition()));plate(holder,f);h.assertTrue(holder.activatePlate(h.getLevel()),"Offline cold field starts");pig.setNoAi(true);h.assertTrue(SpellFields.get(h.getLevel()).forOwner(p.getUUID()).getLast().device().isPresent(),"Device anchor persisted on the field");pig.removeEffect(net.minecraft.world.effect.MobEffects.SLOWNESS);pig.setTicksFrozen(0);h.runAfterDelay(12,()->{h.assertTrue(pig.hasEffect(net.minecraft.world.effect.MobEffects.SLOWNESS),"Device field continues ticking without online owner");h.succeed();});});
        test("m1_holder_delayed_persistence",h->{var p=owner(h);var at=h.absolutePos(new BlockPos(2,1,2));var holder=station(h,"rune_holder",at,p,100);var base=ExampleFormulas.light(p.getUUID());var nodes=new ArrayList<>(base.nodes());nodes.add(new Formula.Node("delay","badspell:delay",0,0,Map.of("ticks",new Value.Number(20))));var edges=new ArrayList<>(base.edges());edges.removeIf(e->e.to().equals("activate")&&e.port().equals("trigger"));edges.add(new Formula.Edge("impulse","delay","trigger"));edges.add(new Formula.Edge("delay","activate","trigger"));var f=new Formula(base.id(),p.getUUID(),1,"delay",nodes,edges,base.output(),100);plate(holder,f);h.assertTrue(!holder.activatePlate(h.getLevel())&&holder.scheduled()&&holder.energyStored()==100,"Delay schedules without debit");var tag=holder.saveWithFullMetadata(h.getLevel().registryAccess());var restored=(StationBlockEntity)BlockEntity.loadStatic(at,holder.getBlockState(),tag,h.getLevel().registryAccess());h.assertTrue(restored!=null&&restored.scheduled()&&p.getUUID().equals(restored.ownerId()),"Full block NBT preserves job, inventory and owner");h.getLevel().setBlockEntity(restored);h.runAfterDelay(25,()->{h.assertTrue(restored.energyStored()==70&&!restored.scheduled(),"Restored job executes exactly once");h.succeed();});});
        test("m1_holder_cancel_and_foreign_menu",h->{var p=owner(h);var at=h.absolutePos(new BlockPos(2,1,2));var holder=station(h,"rune_holder",at,p,100);var f=ExampleFormulas.template("night_lamp",p.getUUID(),SpellEffects.position(h.getLevel(),at));plate(holder,f);holder.activatePlate(h.getLevel());h.assertTrue(holder.scheduled(),"Periodic graph is stored");var intruder=owner(h);var menu=new StationMenu(1,intruder.getInventory(),holder,holder.data);h.assertTrue(!menu.clickMenuButton(intruder,0)&&holder.scheduled(),"Foreign player cannot stop job");menu=new StationMenu(1,p.getInventory(),holder,holder.data);h.assertTrue(menu.clickMenuButton(p,0)&&!holder.scheduled(),"Owner can stop via menu intent");h.succeed();});
        test("m1_moon_salt_recipe_is_executable",h->{var p=owner(h);var at=h.absolutePos(new BlockPos(2,1,2));var table=station(h,"alchemy_table",at,p,100);table.setItem(0,new ItemStack(ModContent.item("moon_brew"),2));h.runAfterDelay(245,()->{h.assertTrue(table.getItem(7).is(ModContent.item("moon_essence")),"First run makes essence");table.setItem(7,ItemStack.EMPTY);table.setItem(0,new ItemStack(ModContent.item("moon_brew"),2));table.setItem(1,new ItemStack(Items.QUARTZ));h.runAfterDelay(245,()->{h.assertTrue(table.getItem(7).is(ModContent.item("moon_salt")),"Adding quartz invalidates the cached essence recipe");h.assertTrue(table.energyStored()==60,"Both recipes pay exact energy");h.succeed();});});});
    }
    public static void register(IEventBus bus){FUNCTIONS.register(bus);bus.addListener(M1CompletionTests::tests);}
    private static void tests(RegisterGameTestsEvent event){var env=event.registerEnvironment(Identifier.fromNamespaceAndPath("badspell","m1_completion"));for(String name:NAMES){var id=Identifier.fromNamespaceAndPath("badspell",name);event.registerTest(id,new FunctionGameTestInstance(ResourceKey.create(Registries.TEST_FUNCTION,id),new TestData<>(env,Identifier.fromNamespaceAndPath("badspell","test_room"),1000,0,true)));}}
}
